func twoSum(nums []int, target int) (int, int, bool) {
	idx := make(map[int]int)
	for i, x := range nums {
		idx[x] = i
	}
	for i, x := range nums {
		if j, ok := idx[target-x]; ok {
			return i, j, true
		}
	}
	return 0, 0, false
}

func total(values []int32) int32 {
	var s int32
	for _, v := range values {
		s += v
	}
	return s
}

func search(a []int, target int) int {
	lo, hi := 0, len(a)
	for lo <= hi {
		mid := lo + (hi-lo)/2
		if a[mid] == target {
			return mid
		}
		if a[mid] < target {
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}
	return -1
}

