			hi = mid - 1
		}
	}
	return -1
}

func isValid(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := make([]rune, 0, len(s))
	for _, r := range s {
		switch r {
		case '(', '[', '{':
			stack = append(stack, r)
		case ')', ']', '}':
			if len(stack) == 0 || stack[len(stack)-1] != pairs[r] {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	return len(stack) == 0
}

beats.solution:
Здесь три разных риска:
- время: O(n²) не уложится;
- память: дополнительная структура на n элементов может не поместиться;
- переполнение: сумма выйдет за диапазон `int32`.

Знаковые целые в Go переполняются молча, без panic: сумма может стать отрицательной. Лечится накоплением в `int64` и уточнением диапазона значений.
